<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { MobileApiError } from '../../api/client'
import { useB4Store } from '../../stores/b4'
import { B12_REPORT_REASONS, createB12SocialReport, getB12SocialLeaderboard, listB12NotificationPreferences, listB12Notifications, updateB12NotificationPreference, type B12Leaderboard, type B12ReportReason } from '../../api/b12'
import { b12T } from '../../platform/b12-i18n'
import { openUniPage } from '../../platform/uni-runtime'

type B12ViewStatus = 'idle' | 'loading' | 'success' | 'empty' | 'permission' | 'offline' | 'recovery' | 'error'
type PreferenceKey = 'roomInteractions' | 'focusReminders' | 'system' | 'doNotDisturb'
const CANONICAL_NOTIFICATION_TYPE_BY_KEY: Record<PreferenceKey, string> = { roomInteractions: 'ROOM_INTERACTIONS', focusReminders: 'FOCUS_REMINDERS', system: 'SYSTEM', doNotDisturb: 'DO_NOT_DISTURB' }
const PREFERENCE_KEY_BY_NOTIFICATION_TYPE: Record<string, PreferenceKey> = { ROOM_INTERACTIONS: 'roomInteractions', FOCUS_REMINDERS: 'focusReminders', SYSTEM: 'system', DO_NOT_DISTURB: 'doNotDisturb', roomInteractions: 'roomInteractions', focusReminders: 'focusReminders', system: 'system', doNotDisturb: 'doNotDisturb' }
const CANONICAL_NOTIFICATION_TYPES = new Set(Object.values(CANONICAL_NOTIFICATION_TYPE_BY_KEY))
const b4 = useB4Store(); const roomIndex = ref(0); const leaderboard = ref<B12Leaderboard | null>(null); const reportReason = ref<B12ReportReason>('SPAM'); const reasons = [...B12_REPORT_REASONS]; const status = ref<B12ViewStatus>('idle'); const actionKey = ref<string | null>(null); const lastError = ref<string | null>(null); const lastReport = ref<{ status: string; reviewMode: string } | null>(null); const notificationCount = ref(0); const notificationPreferences = ref<Record<PreferenceKey, boolean>>({ roomInteractions: true, focusReminders: true, system: true, doNotDisturb: false }); const preferenceVersions = ref<Partial<Record<PreferenceKey, number>>>({}); const lastLoadedRoomId = ref('')
const roomNames = computed(() => b4.rooms.map((room) => room.name)); const selectedRoomId = computed(() => b4.rooms[roomIndex.value]?.roomId ?? '')
function isRecord(value: unknown): value is Record<string, unknown> { return typeof value === 'object' && value !== null && !Array.isArray(value) }
function sourceOf(value: unknown): Record<string, unknown> { const root = isRecord(value) && isRecord(value.data) ? value.data : value; return isRecord(root) ? root : {} }
function text(value: unknown, fallback = ''): string { return typeof value === 'string' && value.trim() ? value : fallback }
function number(value: unknown, fallback = 0): number { return typeof value === 'number' && Number.isFinite(value) ? value : fallback }
function errorStatus(error: unknown): B12ViewStatus { if (error instanceof MobileApiError) return error.status === 0 ? 'offline' : error.status === 401 || error.status === 403 ? 'permission' : error.status === 409 ? 'recovery' : 'error'; return 'error' }
function errorMessage(error: unknown, fallback: string): string { if (error instanceof MobileApiError && error.status === 401) return '请先登录后查看社交数据。'; return error instanceof Error && error.message ? error.message : fallback }
function parseLeaderboard(value: unknown): B12Leaderboard | null { const root = sourceOf(value); if (!Array.isArray(root.entries)) return null; return { kind: text(root.kind, 'FOCUS_MINUTES'), period: text(root.period, 'DAY'), entries: root.entries.filter(isRecord).map((entry) => ({ rank: number(entry.rank), displayMode: text(entry.displayMode, 'ANONYMOUS'), displayName: typeof entry.displayName === 'string' ? entry.displayName : undefined, score: number(entry.score), qualifiedUnits: number(entry.qualifiedUnits), isSelf: entry.isSelf === true, targetSeatIndex: typeof entry.targetSeatIndex === 'number' ? entry.targetSeatIndex : undefined })).filter((entry) => entry.rank > 0) } }
function parsePreference(value: unknown): void { const source = Array.isArray(value) ? value : isRecord(value) && Array.isArray(value.data) ? value.data : []; const canonicalSeen = new Set<PreferenceKey>(); for (const item of source) { if (!isRecord(item) || typeof item.notificationType !== 'string') continue; const key = PREFERENCE_KEY_BY_NOTIFICATION_TYPE[item.notificationType]; if (!key || (canonicalSeen.has(key) && !CANONICAL_NOTIFICATION_TYPES.has(item.notificationType))) continue; notificationPreferences.value[key] = item.enabled !== false; if (CANONICAL_NOTIFICATION_TYPES.has(item.notificationType)) { if (typeof item.version === 'number') preferenceVersions.value[key] = item.version; canonicalSeen.add(key) } else delete preferenceVersions.value[key] } }
async function loadLeaderboard(roomId: string): Promise<void> { if (!roomId || actionKey.value) return; lastLoadedRoomId.value = roomId; actionKey.value = `leaderboard.${roomId}`; status.value = 'loading'; try { leaderboard.value = parseLeaderboard(await getB12SocialLeaderboard(roomId)); status.value = leaderboard.value?.entries.length ? 'success' : 'empty' } catch (error) { status.value = errorStatus(error); lastError.value = errorMessage(error, '排行榜读取失败；未在本地计算或修改排名。') } finally { actionKey.value = null } }
function selectRoom(event: { detail: { value: number } }): void { roomIndex.value = Number(event.detail.value) || 0; if (selectedRoomId.value) void loadLeaderboard(selectedRoomId.value) }
function report(entry: { targetSeatIndex?: number; isSelf: boolean }): void { if (entry.isSelf || !entry.targetSeatIndex || !selectedRoomId.value || actionKey.value) return; actionKey.value = `report.${selectedRoomId.value}.${entry.targetSeatIndex}`; void createB12SocialReport(selectedRoomId.value, entry.targetSeatIndex, reportReason.value).then((value) => { const root = sourceOf(value); lastReport.value = { status: text(root.status, 'RECEIVED'), reviewMode: text(root.reviewMode, 'MANUAL') }; status.value = 'success'; lastError.value = null }).catch((error: unknown) => { status.value = errorStatus(error); lastError.value = errorMessage(error, '举报提交失败；未使用自由文本或本地审核结果。') }).finally(() => { actionKey.value = null }) }
function selectReason(event: { detail: { value: number } }): void { reportReason.value = reasons[Number(event.detail.value)] ?? 'SPAM' }
function openLogin(): void { openUniPage('/pages/login/login') }
function savePreference(key: PreferenceKey, value: boolean): void { if (actionKey.value) return; actionKey.value = `preference.${key}`; void updateB12NotificationPreference(key, value, preferenceVersions.value[key]).then((raw) => { parsePreference([raw]); status.value = 'success' }).catch((error: unknown) => { status.value = errorStatus(error); lastError.value = errorMessage(error, '通知偏好保存失败。') }).finally(() => { actionKey.value = null }) }
watch(() => b4.rooms.length, (length) => { if (length && roomIndex.value >= length) roomIndex.value = 0; if (selectedRoomId.value && selectedRoomId.value !== lastLoadedRoomId.value) void loadLeaderboard(selectedRoomId.value) }, { immediate: true })
onMounted(async () => { try { parsePreference(await listB12NotificationPreferences()); const messages = await listB12Notifications(); const root = Array.isArray(messages) ? messages : sourceOf(messages); notificationCount.value = Array.isArray(root) ? root.length : Array.isArray(root.items) ? root.items.length : 0 } catch { /* explicit defaults remain until the service confirms state */ } })
</script>

<template>
  <view class="b12-card"><view class="b12-heading"><view><text class="b12-kicker">LEADERBOARD · REPORT</text><text class="b12-title">{{ b12T('social.leaderboard') }}</text></view><text class="b12-muted">{{ b12T('social.privacy') }}</text></view><picker v-if="roomNames.length" :range="roomNames" :value="roomIndex" @change="selectRoom"><view class="b12-picker">{{ roomNames[roomIndex] }}</view></picker><view v-if="actionKey?.startsWith('leaderboard.')" class="b12-state-box">{{ b12T('social.loadingLeaderboard') }}</view><view v-else-if="leaderboard?.entries.length" class="b12-list"><view v-for="entry in leaderboard.entries" :key="`${entry.rank}-${entry.targetSeatIndex ?? 'global'}`" class="b12-entry"><view><text class="b12-strong">#{{ entry.rank }} · {{ entry.displayName ?? '匿名学员' }}</text><text class="b12-muted">{{ entry.displayMode }} · {{ b12T('social.focusSeconds') }} {{ entry.qualifiedUnits * 60 }}s</text></view><button v-if="!entry.isSelf && entry.targetSeatIndex" class="b12-button secondary" type="button" :disabled="Boolean(actionKey) || !b4.online" @click="report(entry)">{{ actionKey === `report.${selectedRoomId}.${entry.targetSeatIndex}` ? b12T('social.submittingReport') : b12T('social.report') }}</button><text v-else class="b12-muted">{{ entry.isSelf ? b12T('social.noSelfReport') : b12T('social.privacy') }}</text></view></view><text v-else class="b12-state-box">{{ b12T('social.emptyLeaderboard') }}</text><picker :range="reasons" :value="reasons.indexOf(reportReason)" @change="selectReason"><view class="b12-picker">{{ b12T('social.reportReason') }}：{{ reportReason }}</view></picker><text v-if="lastReport" class="b12-result">{{ b12T('social.reportReceived') }} · {{ lastReport.status }} · {{ lastReport.reviewMode }}</text><text v-if="status === 'permission'" class="b12-state-box">{{ b12T('status.permission') }}</text><button v-if="status === 'permission'" class="b12-button secondary" type="button" @click="openLogin">去登录</button><text v-else-if="status === 'offline'" class="b12-state-box">{{ b12T('status.offline') }}</text><text v-else-if="status === 'recovery'" class="b12-state-box">{{ b12T('status.recovery') }}</text><text v-else-if="lastError" class="b12-state-box">{{ lastError }}</text></view>
  <view class="b12-card"><view class="b12-heading"><view><text class="b12-kicker">NOTIFICATION CENTER</text><text class="b12-title">{{ b12T('notifications.preferences') }}</text></view><text class="b12-muted">{{ notificationCount }} 条</text></view><view class="b12-preferences"><label><switch :disabled="Boolean(actionKey)" :checked="notificationPreferences.roomInteractions" @change="savePreference('roomInteractions', $event.detail.value)" /><text>{{ b12T('notifications.room') }}</text></label><label><switch :disabled="Boolean(actionKey)" :checked="notificationPreferences.focusReminders" @change="savePreference('focusReminders', $event.detail.value)" /><text>{{ b12T('notifications.focus') }}</text></label><label><switch :disabled="Boolean(actionKey)" :checked="notificationPreferences.system" @change="savePreference('system', $event.detail.value)" /><text>{{ b12T('notifications.system') }}</text></label><label><switch :disabled="Boolean(actionKey)" :checked="notificationPreferences.doNotDisturb" @change="savePreference('doNotDisturb', $event.detail.value)" /><text>{{ b12T('notifications.dnd') }}</text></label></view></view>
</template>

<style scoped lang="scss">
.b12-card{display:grid;gap:16rpx;margin-top:24rpx;padding:22rpx;border:1rpx solid var(--yx-border);border-radius:16rpx;background:var(--yx-surface-card)}.b12-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:16rpx}.b12-kicker{display:block;color:var(--yx-brand);font-size:21rpx;font-weight:800;letter-spacing:2rpx}.b12-title{display:block;margin-top:8rpx;font-size:34rpx;font-weight:750}.b12-muted{color:var(--yx-text-secondary);font-size:22rpx;line-height:1.6}.b12-strong{display:block;color:var(--yx-text-primary);font-size:25rpx;font-weight:700}.b12-state-box{display:block;padding:18rpx;border:1rpx dashed var(--yx-border);border-radius:12rpx;color:var(--yx-text-secondary);font-size:23rpx;line-height:1.6}.b12-picker{min-height:64rpx;padding:0 16rpx;border:1rpx solid var(--yx-border);border-radius:12rpx;color:var(--yx-brand);background:var(--yx-surface-card);font-size:22rpx;line-height:64rpx}.b12-list{display:grid;gap:12rpx}.b12-entry{display:flex;align-items:center;justify-content:space-between;gap:12rpx;padding:18rpx;border:1rpx solid var(--yx-border);border-radius:12rpx}.b12-entry>view{display:grid;gap:6rpx}.b12-button{min-height:64rpx;padding:0 18rpx;border:0;border-radius:12rpx;color:#fff;background:var(--yx-brand);font-size:22rpx;line-height:64rpx}.b12-button.secondary{border:1rpx solid var(--yx-border);color:var(--yx-brand);background:var(--yx-surface-card)}.b12-button:disabled{opacity:.5}.b12-result{display:block;padding:14rpx;border-radius:10rpx;color:var(--yx-success-strong);background:var(--yx-success-soft);font-size:22rpx;line-height:1.6}.b12-preferences{display:grid;grid-template-columns:repeat(2,1fr);gap:12rpx}.b12-preferences label{display:flex;align-items:center;gap:10rpx;padding:12rpx;border:1rpx solid var(--yx-border);border-radius:10rpx;color:var(--yx-text-secondary);font-size:22rpx}@media(max-width:520px){.b12-entry{align-items:flex-start;flex-direction:column}.b12-button{width:100%}}
</style>
